    val rem = normalized % 90
    val k = (normalized / 90).toInt()
    val option1 = k
    val option2 = (k + 1) % 4
    val dev1 = (rem).coerceAtMost(90 - rem)
    val dev2 = (90 - rem).coerceAtMost(rem)
    if (dev1 <= dev2) {
        println(option1)
    } else {
        println(option2)
    }
}
